// Spectrum analyzer window (bsc lan analyzer) — the detached surface opened by
// `bsc widget open spectrum`. A WATERFALL above, what the assistant can say
// below.
//
// WHY A SEPARATE WINDOW. It survives the main surface being wedged, which is
// also why the window is built by the app's Rust side rather than by this web
// view — an escape hatch routed through the thing it escapes is not one.
//
// WHY A WATERFALL AND NOT A BAR CHART. A bar per bin answers "what does this
// channel look like right now" and discards the two things an operator watches
// for: where a signal sits in the BAND, and how long it has been there. A burst
// and a permanent emitter draw the same bar. Here x is frequency across
// everything we can see, y is time with the newest window on top, and colour is
// signal strength — so duration stops being a number and becomes vertical
// extent. A persistent emitter is a stripe; a burst is a dash.
//
// THE SPAN IS WHAT WE OBSERVED, NEVER A BAND CONSTANT. The radio is parked on
// one channel today, so the axis is that channel's 20 MHz; hopping widens it and
// the axis follows. Drawing 2400-2500 with most of it blank would assert we had
// looked at the whole band and found it empty — the same lie as rendering a
// spectrum of zeroes.
//
// THE BINS ARE PEAKS, NOT AVERAGES. The sensor aggregates ~666 sweeps/sec down
// to one record per channel per window and keeps the per-bin MAXIMUM, because a
// brief microwave burst is what this tier exists to catch and averaging it
// against quiet sweeps is how it hides.
//
// WHERE THE DATA COMES FROM, and what does NOT come with it. The app's Rust half
// subscribes to the sensor's sealed UDP stream, verifies the Ed25519 signature,
// decrypts and decodes; this view receives already-authenticated records over a
// Tauri event and holds NO key of any kind.
import { useEffect, useMemo, useState } from "react";
import { listen } from "@tauri-apps/api/event";
import { Box } from "@/shared/ui/layout/Box";
import { Stack } from "@/shared/ui/layout/Stack";
import { Text } from "@/shared/ui/typography/Text";

export type SpectrumBins = {
  /** Which sensor heard this — from the key that verified it, never a claim. */
  sensor: string;
  freqMhz: number;
  sweeps: number;
  noiseDbm: number;
  peakMagnitude: number;
  peakBin: number;
  binMax: number[];
  /** Milliseconds since the subscription started. Absent on a fixture. */
  receivedAtMs?: number;
};

/** What the subscription can say about whether the sensor is still there. */
export type LivenessState = "never-heard" | "healthy" | "late" | "silent";

export type Liveness = {
  /** Which sensor this verdict is about. Every sensor is judged separately. */
  sensor: string;
  state: LivenessState;
  sinceMs: number;
  overdueByMs: number;
};

/** Before anything at all has arrived — NOT a healthy stream. */
export const NEVER_HEARD: Liveness = {
  sensor: "",
  state: "never-heard",
  sinceMs: 0,
  overdueByMs: 0,
};

/** One observed window: a record, and when it landed. */
export type Row = { at: number; bins: SpectrumBins };

/** The frequency extent of the waterfall, in MHz. */
export type Span = { loMhz: number; hiMhz: number };

/**
 * How many windows the waterfall keeps.
 *
 * The sensor's emit cadence sets what one row MEANS, and at 4 Hz this is a
 * couple of minutes of air. Deeper than the panel can show on purpose: the
 * container clips, and a history shorter than the view would leave the bottom
 * of the waterfall permanently blank.
 */
export const HISTORY = 900;

/** An HT20 channel is 20 MHz wide, however many bins the radio reports. */
export const CHANNEL_WIDTH_MHZ = 20;

/**
 * The narrowest dB window the ramp will spread itself over.
 *
 * Without a floor on the RANGE, a perfectly flat band would have its own
 * quantisation noise stretched across the whole ramp and drawn as violent
 * structure. Below this, the scale stops expanding and the picture is allowed
 * to look as uniform as it is.
 */
export const MIN_RANGE_DB = 6;

/** Centre frequency of one FFT bin. */
export function binFrequencyMhz(centreMhz: number, bin: number, bins: number): number {
  return centreMhz - CHANNEL_WIDTH_MHZ / 2 + (CHANNEL_WIDTH_MHZ * (bin + 0.5)) / bins;
}

/** The [low, high] MHz edges of one bin — what the waterfall needs to place it. */
export function binEdgesMhz(centreMhz: number, bin: number, bins: number): [number, number] {
  const lo = centreMhz - CHANNEL_WIDTH_MHZ / 2 + (CHANNEL_WIDTH_MHZ * bin) / bins;
  return [lo, lo + CHANNEL_WIDTH_MHZ / bins];
}

/**
 * Estimated signal strength for one bin, in dBm.
 *
 * ESTIMATED, AND SAID TO BE, WHEREVER IT IS SHOWN. ath9k reports a per-bin FFT
 * magnitude and a per-window noise floor, not a calibrated power. This is
 * decibels above that reported floor, and `floorMagnitude` is the magnitude the
 * floor CORRESPONDS to.
 *
 * MEASURED, and it is why the floor is a parameter rather than 1: on this radio
 * the quietest bins sit around magnitude 85, not 1. Anchoring at 1 put every
 * real bin 38–48 dB "above the noise", so the whole band drew as saturated red
 * and 80% of the ramp was unreachable. A scale whose bottom cannot be reached
 * is not a scale.
 *
 * A magnitude at or below the floor IS the floor, never negative infinity.
 */
export function binDbm(magnitude: number, noiseDbm: number, floorMagnitude: number): number {
  const floor = Math.max(1, floorMagnitude);
  if (magnitude <= floor) return noiseDbm;
  return noiseDbm + 20 * Math.log10(magnitude / floor);
}

/** The magnitude extent actually present in the history. */
export type Extent = { floorMag: number; ceilMag: number };

/**
 * The magnitude range the colours should span, taken from what has been SEEN.
 *
 * Quantiles rather than min and max: one dead bin or one saturated sample would
 * otherwise set an endpoint and flatten everything between. A band with no
 * structure keeps a floor on its range (see [`MIN_RANGE_DB`]) so its own noise
 * is not magnified into a picture.
 */
export function extentOf(rows: Row[]): Extent {
  const all: number[] = [];
  for (const r of rows) for (const v of r.bins.binMax) all.push(v);
  if (all.length === 0) return { floorMag: 1, ceilMag: 255 };
  all.sort((a, b) => a - b);
  const q = (p: number) => all[Math.min(all.length - 1, Math.max(0, Math.floor(p * (all.length - 1))))];
  const floorMag = Math.max(1, q(0.05));
  const ceilMag = Math.max(floorMag * Math.pow(10, MIN_RANGE_DB / 20), q(0.995));
  return { floorMag, ceilMag };
}

type Stop = { at: number; rgb: [number, number, number] };

/** The ramp, dark to hot. Classic for a waterfall, and legible on a dark ground. */
const RAMP: Stop[] = [
  { at: 0.0, rgb: [10, 12, 24] },
  { at: 0.25, rgb: [24, 60, 150] },
  { at: 0.5, rgb: [20, 160, 160] },
  { at: 0.7, rgb: [90, 200, 70] },
  { at: 0.85, rgb: [240, 200, 50] },
  { at: 1.0, rgb: [240, 70, 50] },
];

/** Colour for a strength, as a fraction of the ramp. Pure, so the scale is testable. */
export function rampColor(t: number): string {
  const x = Math.max(0, Math.min(1, t));
  let lo = RAMP[0];
  let hi = RAMP[RAMP.length - 1];
  for (let i = 0; i < RAMP.length - 1; i++) {
    if (x >= RAMP[i].at && x <= RAMP[i + 1].at) {
      lo = RAMP[i];
      hi = RAMP[i + 1];
      break;
    }
  }
  const span = hi.at - lo.at || 1;
  const k = (x - lo.at) / span;
  const c = (a: number, b: number) => Math.round(a + (b - a) * k);
  return `rgb(${c(lo.rgb[0], hi.rgb[0])},${c(lo.rgb[1], hi.rgb[1])},${c(lo.rgb[2], hi.rgb[2])})`;
}

/** The dB span the ramp covers, from the observed extent. */
export function rangeDb(e: Extent): number {
  return Math.max(MIN_RANGE_DB, 20 * Math.log10(e.ceilMag / Math.max(1, e.floorMag)));
}

/** Where a strength sits on the ramp. */
export function strengthFraction(dbm: number, noiseDbm: number, e: Extent): number {
  return Math.max(0, Math.min(1, (dbm - noiseDbm) / rangeDb(e)));
}

/** Colour for one bin's magnitude, against the range actually observed. */
export function strengthColor(magnitude: number, noiseDbm: number, e: Extent): string {
  return rampColor(strengthFraction(binDbm(magnitude, noiseDbm, e.floorMag), noiseDbm, e));
}

/**
 * The frequency extent of everything observed — never a band constant.
 *
 * `null` when nothing has arrived, so the caller renders the empty state rather
 * than an axis with no meaning.
 */
export function spanOf(rows: Row[]): Span | null {
  let lo = Infinity;
  let hi = -Infinity;
  for (const r of rows) {
    const n = r.bins.binMax.length;
    if (n === 0) continue;
    lo = Math.min(lo, binEdgesMhz(r.bins.freqMhz, 0, n)[0]);
    hi = Math.max(hi, binEdgesMhz(r.bins.freqMhz, n - 1, n)[1]);
  }
  return Number.isFinite(lo) && Number.isFinite(hi) && hi > lo ? { loMhz: lo, hiMhz: hi } : null;
}

/** Push a record onto the history, newest first, bounded. */
export function pushRow(rows: Row[], bins: SpectrumBins, at: number, cap = HISTORY): Row[] {
  return [{ at, bins }, ...rows].slice(0, cap);
}

/** The colour a frequency region gets when NOTHING was looked at there. */
export const UNOBSERVED = "rgba(255,255,255,0.045)";

const pct = (v: number) => `${Math.round(v * 1000) / 1000}%`;

/**
 * One row as a CSS gradient with hard stops — one element per window instead of
 * one per bin, which is the difference between 120 nodes and 6,720.
 *
 * A ROW COVERS ONLY WHAT IT OBSERVED. The rest of the span is [`UNOBSERVED`],
 * visibly not the same as quiet: a hopping radio's rows are honest stripes of
 * where it actually was, and painting the gaps dark would claim it heard silence
 * on channels it never visited.
 */
export function rowGradient(row: Row, span: Span, extent: Extent): string {
  const width = span.hiMhz - span.loMhz;
  const n = row.bins.binMax.length;
  if (width <= 0 || n === 0) return UNOBSERVED;
  const at = (mhz: number) => ((mhz - span.loMhz) / width) * 100;
  const parts: string[] = [];
  const [firstLo] = binEdgesMhz(row.bins.freqMhz, 0, n);
  const [, lastHi] = binEdgesMhz(row.bins.freqMhz, n - 1, n);
  const head = at(firstLo);
  const tail = at(lastHi);
  // The unobserved margins keep HARD edges. They are a statement about what was
  // looked at, not a measurement, and fading into them would blur the boundary
  // between "quiet" and "never checked" — the one distinction this display
  // exists to keep.
  if (head > 0) parts.push(`${UNOBSERVED} 0%`, `${UNOBSERVED} ${pct(head)}`);
  // One stop per bin CENTRE, so each measured value lands exactly where it was
  // measured and the browser interpolates between them. The bins are 0.357 MHz
  // apart and the panel is ~950px wide, so hard-edged blocks were 17px of flat
  // colour each — the radio's resolution is 56 samples either way, but there is
  // no reason to draw them as a staircase.
  const edge = (v: number) => `${strengthColor(v, row.bins.noiseDbm, extent)}`;
  parts.push(`${edge(row.bins.binMax[0])} ${pct(head)}`);
  for (let i = 0; i < n; i++) {
    const c = binFrequencyMhz(row.bins.freqMhz, i, n);
    parts.push(`${edge(row.bins.binMax[i])} ${pct(at(c))}`);
  }
  parts.push(`${edge(row.bins.binMax[n - 1])} ${pct(tail)}`);
  if (tail < 100) parts.push(`${UNOBSERVED} ${pct(tail)}`, `${UNOBSERVED} 100%`);
  return `linear-gradient(to right, ${parts.join(", ")})`;
}

/**
 * How tall one window's band is, in px. The y axis is built from this.
 *
 * ONE, because the vertical is the axis that carries information. A row is one
 * emitted window, so the sensor's cadence sets what a row means and the drawing
 * should not then discard half of it: at 10 Hz a 1px row gives a 340px panel
 * about thirty-four seconds of air at full temporal detail, where 4px would
 * have shown eight.
 */
export const ROW_PX = 1;

/**
 * The frequency axis strip above the waterfall, in px.
 *
 * NAMED because two things measure from it: the strip itself, and the time
 * gutter beside it, which must start where the first ROW starts rather than
 * where the panel starts or the whole time scale reads one label out.
 */
export const AXIS_PX = 16;

/** A label on the time axis: which row it sits beside, and what it reads. */
export type TimeTick = { index: number; label: string };

/**
 * Labels down the time axis, derived from the rows' own timestamps.
 *
 * FROM THE DATA, NOT FROM THE ROW COUNT. Windows do not arrive on a perfect
 * cadence — a wedged radio, a late datagram or a restarted sensor all stretch
 * the gap — so labelling every Nth row "N seconds" would draw a clock that is
 * confidently wrong. Each tick reports the age of the row it actually sits
 * beside.
 *
 * The newest row is always labelled, because "now" is the anchor everything
 * else is read against.
 */
export function timeTicks(rows: Row[], everyRows = 15): TimeTick[] {
  if (rows.length === 0) return [];
  const newest = rows[0].at;
  const out: TimeTick[] = [{ index: 0, label: "now" }];
  for (let i = everyRows; i < rows.length; i += everyRows) {
    const age = Math.max(0, newest - rows[i].at);
    out.push({ index: i, label: `-${ageLabel(age)}` });
  }
  return out;
}

/**
 * Which sensors are represented in the history, in first-seen order.
 *
 * A waterfall blended from several radios without saying so is a lie about
 * where anything was heard: one sensor's quiet band and another's busy one
 * average into a picture neither of them saw. Naming the contributors is the
 * minimum honesty until the rows are separated per sensor.
 */
export function contributingSensors(rows: Row[]): string[] {
  const seen: string[] = [];
  for (const r of rows) {
    const n = r.bins.sensor;
    if (n && !seen.includes(n)) seen.push(n);
  }
  return seen;
}

/** Human-readable age, for a label rather than a calculation. */
export function ageLabel(ms: number): string {
  if (ms < 1000) return `${ms}ms`;
  const s = Math.floor(ms / 1000);
  if (s < 120) return `${s}s`;
  return `${Math.floor(s / 60)}m`;
}

/**
 * Whether what is on screen may be presented as the air RIGHT NOW.
 *
 * Only `healthy` may. `late` and `silent` still render the history — it is the
 * most recent truth there is — but marked, because the alternative is a display
 * that quietly ages into a lie.
 */
export function isCurrent(l: Liveness): boolean {
  // A verdict sitting EXACTLY on its deadline is not yet late, and a banner
  // reading "SENSOR LATE by 0ms" over a waterfall that is visibly filling is
  // noise — the kind that teaches a reader to ignore the banner that matters.
  // Seen on screen: 157 windows in 38 seconds, newest row "now", and a late
  // warning with nothing overdue.
  if (l.state === "late" && l.overdueByMs === 0) return true;
  return l.state === "healthy";
}

/**
 * The banner over a display that may no longer be the air right now.
 *
 * EXHAUSTIVE over the state, not an if/else on `silent`. The two-branch version
 * put NEVER-HEARD into the `late` arm, so a window whose liveness had never
 * arrived rendered "SENSOR LATE by 0ms" over a waterfall that was filling
 * perfectly — a confident, specific, wrong claim, which is worse than an
 * unhelpful one because it sends a reader after a sensor that is fine.
 */
export function staleBanner(l: Liveness): string {
  switch (l.state) {
    case "healthy":
      return "";
    case "never-heard":
      return "NO LIVENESS YET — rows are arriving but the sensor's own health has not been reported.";
    case "late":
      return `SENSOR LATE by ${ageLabel(l.overdueByMs)} — this is the LAST of what it sent, not the air now.`;
    case "silent":
      return `SENSOR SILENT for ${ageLabel(l.sinceMs)} — this is the LAST of what it sent, not the air now.`;
  }
}

/**
 * What an empty panel should say, given whether the sensor is being heard.
 *
 * THE TWO CASES LOOK IDENTICAL AND ARE NOT THE SAME PROBLEM. A subscriber that
 * hears nothing has a network, key or sensor fault. One that hears the sensor
 * perfectly and receives no SPECTRUM has a radio fault. Measured once, at
 * length: an hour of establishing from outside what this line says in six words.
 */
export function emptyStateDiagnosis(l: Liveness): string {
  switch (l.state) {
    case "never-heard":
      return "Nothing has been heard from the sensor at all — check the address and the keys.";
    case "healthy":
      return `The sensor IS heard (${ageLabel(l.sinceMs)} ago) but is sending no spectrum — its radio is producing nothing.`;
    case "late":
      return `The sensor is late by ${ageLabel(l.overdueByMs)} and has sent no spectrum.`;
    case "silent":
      return `The sensor has been silent for ${ageLabel(l.sinceMs)} — treat the stream as gone.`;
  }
}

/**
 * Subscribe to the app's LAN stream. Returns the observed history and what the
 * subscription can say about the sensor's liveness.
 *
 * The liveness event carries the CURRENT verdict rather than only transitions,
 * so a window opened long after the last change still learns the state — "no
 * liveness yet" must not render the same as "healthy".
 */
export function useLanSpectrum(): { rows: Row[]; liveness: Liveness } {
  const [rows, setRows] = useState<Row[]>([]);
  const [liveness, setLiveness] = useState<Liveness>(NEVER_HEARD);

  useEffect(() => {
    let disposed = false;
    const spectrum = listen<SpectrumBins>("lan://spectrum", (e) => {
      if (!disposed) setRows((prev) => pushRow(prev, e.payload, e.payload.receivedAtMs ?? Date.now()));
    });
    const live = listen<Liveness>("lan://liveness", (e) => {
      if (!disposed) setLiveness(e.payload);
    });
    return () => {
      disposed = true;
      void spectrum.then((un) => un());
      void live.then((un) => un());
    };
  }, []);

  return { rows, liveness };
}

function Scale({ noiseDbm, extent }: { noiseDbm: number; extent: Extent }) {
  const steps = [0, 0.25, 0.5, 0.7, 0.85, 1];
  // The endpoints are COMPUTED from what was observed, and shown, so the colours
  // describe themselves. An auto-ranged scale that hid its endpoints would be a
  // picture nobody could read a number off.
  const top = Math.round(noiseDbm + rangeDb(extent));
  return (
    <Box style={{ display: "flex", alignItems: "center", gap: 8, width: "100%" }}>
      <Text as="span" mono tone="dim" style={{ fontSize: 11 }}>
        {noiseDbm} dBm
      </Text>
      <Box
        style={{
          flex: 1,
          height: 8,
          borderRadius: 2,
          background: `linear-gradient(to right, ${steps.map((s) => `${rampColor(s)} ${s * 100}%`).join(", ")})`,
        }}
      />
      <Text as="span" mono tone="dim" style={{ fontSize: 11 }}>
        {top} dBm (est.)
      </Text>
    </Box>
  );
}

/**
 * Tick positions for a span, at a step chosen so the count stays readable.
 *
 * A FIXED 5 MHz STEP DOES NOT SURVIVE A HOPPING RADIO. The span is the union of
 * everything observed, so it grows: one channel is 20 MHz and four ticks, but a
 * radio that has swept 2412 to 2462 spans 70 MHz and fifteen, which overlap
 * into an unreadable smear. The step is therefore picked FROM the span — 1, 2,
 * 5, 10, 20, 50 … — the same 1-2-5 progression any axis uses, so the labels
 * stay round numbers rather than becoming arbitrary.
 */
export function axisTicks(span: Span, maxTicks = 8): number[] {
  const width = span.hiMhz - span.loMhz;
  if (!(width > 0)) return [];
  const steps = [1, 2, 5, 10, 20, 50, 100, 200, 500];
  const step = steps.find((s) => width / s <= maxTicks) ?? steps[steps.length - 1];
  const out: number[] = [];
  for (let f = Math.ceil(span.loMhz / step) * step; f <= span.hiMhz; f += step) out.push(f);
  return out;
}

/**
 * Where a tick's label sits, as a percentage, and how it should be anchored.
 *
 * A LABEL CENTRED ON THE FIRST OR LAST TICK HANGS OFF THE CHART. Half of "2427"
 * outside the plot is what "the axis overflows" looks like, so the outermost
 * labels anchor to their edge instead of straddling it.
 */
export function tickAnchor(pct: number): { left: string; transform: string } {
  if (pct <= 2) return { left: "0%", transform: "none" };
  if (pct >= 98) return { left: "100%", transform: "translateX(-100%)" };
  return { left: `${pct}%`, transform: "translateX(-50%)" };
}

function Axis({ span }: { span: Span }) {
  const ticks = useMemo(() => axisTicks(span), [span]);
  const width = span.hiMhz - span.loMhz || 1;
  return (
    <Box style={{ position: "relative", height: 16, width: "100%", overflow: "hidden" }}>
      {ticks.map((f) => {
        const p = ((f - span.loMhz) / width) * 100;
        const { left, transform } = tickAnchor(p);
        return (
          <Text
            key={f}
            as="span"
            mono
            tone="dim"
            style={{
              position: "absolute",
              left,
              transform,
              fontSize: 11,
              whiteSpace: "nowrap",
            }}
          >
            {f}
          </Text>
        );
      })}
    </Box>
  );
}

function TimeAxis({ rows }: { rows: Row[] }) {
  const ticks = useMemo(() => timeTicks(rows), [rows]);
  return (
    <Box style={{ position: "relative", width: 54, flex: "0 0 54px" }}>
      {/* Aligned to the BAND, not to the gutter: the frequency axis above the
          waterfall is 16px tall, so every tick is offset by it or the whole
          time scale reads one label out. */}
      {/* CLIPS, and that is the half that was missing. A tick is absolutely
          positioned at its row's offset, so `bottom: 0` bounds the BOX and
          nothing at all bounds the labels inside it: with 900 rows of history
          in a panel that draws a few hundred, every label past the visible
          depth was still painted, running out of the gutter and down the
          window. Clipping here makes the axis end exactly where the drawing
          ends — they are cut by the same edge, so a label can never name a row
          that is not on screen. */}
      <Box style={{ position: "absolute", top: AXIS_PX, left: 0, right: 6, bottom: 0, overflow: "hidden" }}>
        {ticks.map((t) => (
          <Text
            key={t.index}
            as="span"
            mono
            tone="dim"
            style={{
              position: "absolute",
              top: t.index * ROW_PX,
              right: 0,
              fontSize: 10,
              lineHeight: "10px",
              whiteSpace: "nowrap",
            }}
          >
            {t.label}
          </Text>
        ))}
      </Box>
    </Box>
  );
}

function Waterfall({ rows, liveness }: { rows: Row[]; liveness: Liveness }) {
  const span = useMemo(() => spanOf(rows), [rows]);
  const extent = useMemo(() => extentOf(rows), [rows]);

  if (!span) {
    // Never render an empty display as a quiet band: no data and clear air look
    // identical here, and only one of them is good news.
    return (
      <Box style={{ padding: 24, width: "100%" }}>
        <Text as="div" mono tone="dim">
          No spectrum received yet — this is NOT a quiet band.
        </Text>
        <Text as="div" mono style={{ marginTop: 10 }}>
          {emptyStateDiagnosis(liveness)}
        </Text>
        <Text as="div" mono tone="dim" style={{ marginTop: 6, fontSize: 12 }}>
          The sensor emits one aggregated record per channel per window. If nothing
          arrives, check the group and the keys before concluding the air is clear.
        </Text>
      </Box>
    );
  }

  const newest = rows[0].bins;
  const current = isCurrent(liveness);
  return (
    <Stack gap={6} style={{ padding: 12, width: "100%", height: "100%", minHeight: 0 }}>
      <Text as="div" mono style={{ fontSize: 12 }}>
        {span.loMhz.toFixed(0)}–{span.hiMhz.toFixed(0)} MHz observed · {rows.length} window(s) ·{" "}
        {newest.sweeps} sweeps · noise {newest.noiseDbm} dBm
      </Text>
      <Text as="div" mono tone="dim" style={{ fontSize: 11 }}>
        {/* NAMED, because a blended waterfall from several radios is a lie about
            where anything was heard. Which sensors are actually contributing is
            the first thing to check when a band looks quieter than it should. */}
        sensors contributing: {contributingSensors(rows).join(", ") || "—"}
      </Text>
      {!current && (
        <Text as="div" mono tone="dim" style={{ fontSize: 12 }}>
          {staleBanner(liveness)}
        </Text>
      )}
      <Box style={{ display: "flex", width: "100%", flex: 1, minHeight: 120 }}>
        <TimeAxis rows={rows} />
        {/* A BOUNDED COLUMN: the frequency strip at its natural height, the
            waterfall taking exactly what is left. Without `height` + `column`
            here the rows box below has no definite parent, so its own
            `overflow: hidden` has nothing to bite on and it simply grows to
            900px of content. */}
        <Box style={{ flex: 1, minWidth: 0, height: "100%", display: "flex", flexDirection: "column" }}>
          <Axis span={span} />
          <Box
            style={{
              width: "100%",
              // `flex: 1` + `minHeight: 0` is what gives this box a definite
              // height; `overflow: hidden` alone never did anything, because a
              // box sized by its content has nothing to overflow.
              flex: 1,
              minHeight: 0,
              overflow: "hidden",
              border: "1px solid var(--border)",
              opacity: current ? 1 : 0.55,
              display: "flex",
              flexDirection: "column",
            }}
          >
            {rows.map((r) => (
              <Box
                key={`${r.at}-${r.bins.freqMhz}`}
                title={`${r.bins.freqMhz} MHz · ${r.bins.sweeps} sweeps · peak ${r.bins.peakMagnitude} at bin ${r.bins.peakBin}`}
                style={{
                  width: "100%",
                  flex: `0 0 ${ROW_PX}px`,
                  background: rowGradient(r, span, extent),
                }}
              />
            ))}
          </Box>
        </Box>
      </Box>
      <Scale noiseDbm={newest.noiseDbm} extent={extent} />
      <Text as="div" mono tone="dim" style={{ fontSize: 11 }}>
        time runs DOWN from now · colour is signal strength ESTIMATED as dB above the reported noise
        floor, scaled to the range actually observed · per-bin PEAK across each window (not a mean),
        interpolated between the 56 measured bin centres · a faint band is frequency nobody looked at
      </Text>
    </Stack>
  );
}

function Assistant({ notes }: { notes: string[] }) {
  return (
    <Stack gap={6} style={{ padding: 16, overflow: "auto", height: "100%", width: "100%" }}>
      <Text as="div" mono tone="dim" style={{ fontSize: 11 }}>
        ASSISTANT
      </Text>
      {notes.length === 0 ? (
        <Text as="div" mono tone="dim">
          Nothing to report yet.
        </Text>
      ) : (
        notes.map((n, i) => (
          <Text as="div" mono key={i} style={{ fontSize: 12 }}>
            {n}
          </Text>
        ))
      )}
    </Stack>
  );
}

/**
 * The analyzer window: waterfall above, assistant below.
 *
 * Presentational on purpose — it takes what to draw rather than fetching it, so
 * every state it can be in is reachable from a test without a socket.
 * [`LiveSpectrumAnalyzer`] is the half that subscribes.
 *
 * Width and height are STATED at every level, not inherited: percentage heights
 * resolve against a definite parent and `min-height` does not make one, and a
 * stretched flex child collapses to content width the moment an ancestor stops
 * being definite. Both were seen on screen with a green gate, because jsdom has
 * no layout at all.
 */
export function SpectrumAnalyzer({
  rows = [],
  liveness = NEVER_HEARD,
  notes = [],
}: {
  rows?: Row[];
  liveness?: Liveness;
  notes?: string[];
}) {
  return (
    <Stack style={{ height: "100%", width: "100%" }}>
      <Box
        style={{
          flex: "1 1 62%",
          minHeight: 0,
          width: "100%",
          borderBottom: "1px solid var(--border)",
        }}
      >
        <Waterfall rows={rows} liveness={liveness} />
      </Box>
      <Box style={{ flex: "1 1 38%", minHeight: 0, width: "100%" }}>
        <Assistant notes={notes} />
      </Box>
    </Stack>
  );
}

/** The analyzer, wired to the live stream. What the detached window renders. */
export function LiveSpectrumAnalyzer() {
  const { rows, liveness } = useLanSpectrum();
  return <SpectrumAnalyzer rows={rows} liveness={liveness} />;
}
